// Session store: createSessionStore({ path }) keeps the app's sessions in a SQLite file at `path`
// (in memory when no path is given), so they survive a restart.
export function createSessionStore(options = {}) {
  const db = new DatabaseSync(options.path ?? ':memory:');
  db.exec('CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, data TEXT NOT NULL)');
  const put = db.prepare('INSERT INTO sessions (id, data) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data');
  const read = db.prepare('SELECT data FROM sessions WHERE id = ?');
  const del = db.prepare('DELETE FROM sessions WHERE id = ?');
  return {
    set(id, data) {
      put.run(id, JSON.stringify(data));
    },
    get(id) {
      const row = read.get(id);
      return row === undefined ? undefined : JSON.parse(row.data);
    },
    delete(id) {
      del.run(id);
    },
    close() {
      db.close();
    },
  };
}
");
